+
+    @Override
+    public MatchResult match() {
+        return actual.equals(expected)
+            ? MatchResult.match()
+            : MatchResult.noMatch(
+                formatErrorMessage(
+                    actualMappings,
+                    actualSettings,
+                    expectedMappings,
+                    expectedSettings,
+                    "Actual does not equal expected, actual: " + actual + ", expected: " + expected
+                )
+            );
+    }
+}
