+    }
+
+    private MatchResult matchListEquals(final List<Object> actualList, final List<Object> expectedList, boolean ignoreSorting) {
+        if (actualList.size() != expectedList.size()) {
+            return MatchResult.noMatch(
+                formatErrorMessage(
+                    actualMappings,
+                    actualSettings,
+                    expectedMappings,
+                    expectedSettings,
+                    "List lengths do no match, " + prettyPrintLists(actualList, expectedList)
+                )
+            );
+        }
+        if (ignoreSorting) {
+            return matchListsEqualIgnoringSorting(actualList, expectedList)
+                ? MatchResult.match()
+                : MatchResult.noMatch(
+                    formatErrorMessage(
+                        actualMappings,
+                        actualSettings,
+                        expectedMappings,
+                        expectedSettings,
+                        "Lists do not match when ignoring sort order, " + prettyPrintLists(actualList, expectedList)
+                    )
+                );
+        } else {
+            return matchListsEqualExact(actualList, expectedList)
+                ? MatchResult.match()
+                : MatchResult.noMatch(
+                    formatErrorMessage(
+                        actualMappings,
+                        actualSettings,
+                        expectedMappings,
+                        expectedSettings,
+                        "Lists do not match exactly, " + prettyPrintLists(actualList, expectedList)
+                    )
+                );
+        }
+    }
+
+    private static boolean matchListsEqualIgnoringSorting(final List<Object> actualList, final List<Object> expectedList) {
+        return actualList.containsAll(expectedList) && expectedList.containsAll(actualList);
+    }
+
+    private static <T> boolean matchListsEqualExact(List<Object> actualList, List<Object> expectedList) {
